// Direct tests for the public Riccati.dare DARE primitive (the shared engine LQR.lqr and
// Kalman.steadyStateGain build on). The exhaustive DARE-vs-literature and property battery lives in
// ControlLQRTests (via the LQR facade); this file pins the public entry point itself: a scalar
// closed-form solution, an independent DARE residual on a 2x2 instance (m=1, so the R+BᵀSB solve is a
// scalar division -- no CHOP needed to replicate), determinism, and argument-validation throws.
// Templated (float) so codegen emits a float and a double build; every numeric assertion routes
// through Fail[0..3] like the control smoke file.
public class floatRiccatiTests
{
    [BurstCompile(CompileSynchronously = true, FloatPrecision = FloatPrecision.High, FloatMode = FloatMode.Default)]
    public struct TestJob : IJob
    {
        public enum TestType
        {
            ScalarGoldenRatio,       // A=B=Q=R=[1] -> S solves s^2-s-1=0 -> golden ratio (1+sqrt5)/2
            ResidualDoubleIntegrator,// S satisfies S = Q + AᵀSA - AᵀSB(R+BᵀSB)⁻¹BᵀSA to tolerance
            Determinism,             // two back-to-back dares on the same instance -> bit-identical S
            SmallCovarianceScale,    // S(aQ, aR) == a*S(Q, R): the test must stay RELATIVE as ||S||->0
        }

        public TestType Type;
        public NativeArray<float> Fail;   // [0]=flag [1]=got [2]=expected/limit [3]=diff/extra

        public void Execute()
        {
            switch (Type)
            {
                case TestType.ScalarGoldenRatio:
                {
                    var A = One(); var B = One(); var Q = One(); var R = One();
                    var S = new floatMxN(1, 1, Allocator.Temp);

                    var info = Riccati.dare(in A, in B, in Q, in R, ref S);
                    AssertTrue(info.status == RiccatiStatus.Converged);
                    AssertTrue(!info.rankDeficient);
                    AssertClose(S[0, 0], (float)1.6180339887498949, (float)3e-3);   // (1+sqrt5)/2

                    A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); S.Dispose();
                    break;
                }

                case TestType.ResidualDoubleIntegrator:
                {
                    var A = new floatMxN(2, 2, Allocator.Temp);
                    A[0, 0] = (float)1; A[0, 1] = (float)1; A[1, 0] = (float)0; A[1, 1] = (float)1;
                    var B = new floatMxN(2, 1, Allocator.Temp);
                    B[0, 0] = (float)0; B[1, 0] = (float)1;
                    var Q = new floatMxN(2, 2, Allocator.Temp);
                    Q[0, 0] = (float)1; Q[1, 1] = (float)1;
                    var R = new floatMxN(1, 1, Allocator.Temp);
                    R[0, 0] = (float)1;
                    var S = new floatMxN(2, 2, Allocator.Temp);

                    var info = Riccati.dare(in A, in B, in Q, in R, ref S);
                    AssertTrue(info.status == RiccatiStatus.Converged);

                    // Recompute the RHS Q + AᵀSA - AᵀSB(R+BᵀSB)⁻¹BᵀSA via public Blas (m=1: the inner
                    // solve is a scalar 1/(R+BᵀSB)) and assert S equals it componentwise.
                    var SA = new floatMxN(2, 2, Allocator.Temp);
                    Blas.dot(in S, in A, ref SA);                              // SA = S A
                    var AtSA = new floatMxN(2, 2, Allocator.Temp);
                    Blas.dot(in A, in SA, ref AtSA, transposeA: true);         // AᵀSA
                    var SB = new floatMxN(2, 1, Allocator.Temp);
                    Blas.dot(in S, in B, ref SB);                              // SB = S B
                    var BtSB = new floatMxN(1, 1, Allocator.Temp);
                    Blas.dot(in B, in SB, ref BtSB, transposeA: true);         // BᵀSB (scalar)
                    float Rbar = R[0, 0] + BtSB[0, 0];
                    var AtSB = new floatMxN(2, 1, Allocator.Temp);
                    Blas.dot(in A, in SB, ref AtSB, transposeA: true);         // AᵀSB (2x1); BᵀSA = (AᵀSB)ᵀ

                    for (int i = 0; i < 2; i++)
                        for (int j = 0; j < 2; j++)
                        {
                            float rhs = Q[i, j] + AtSA[i, j] - AtSB[i, 0] * AtSB[j, 0] / Rbar;
                            AssertClose(S[i, j], rhs, (float)3e-3);
                        }

                    SA.Dispose(); AtSA.Dispose(); SB.Dispose(); BtSB.Dispose(); AtSB.Dispose();
                    A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); S.Dispose();
                    break;
                }

                case TestType.Determinism:
                {
                    var A = new floatMxN(2, 2, Allocator.Temp);
                    A[0, 0] = (float)1; A[0, 1] = (float)1; A[1, 0] = (float)0; A[1, 1] = (float)1;
                    var B = new floatMxN(2, 1, Allocator.Temp);
                    B[0, 0] = (float)0; B[1, 0] = (float)1;
                    var Q = new floatMxN(2, 2, Allocator.Temp);
                    Q[0, 0] = (float)1; Q[1, 1] = (float)1;
                    var R = new floatMxN(1, 1, Allocator.Temp);
                    R[0, 0] = (float)1;

                    var S1 = new floatMxN(2, 2, Allocator.Temp);
                    var i1 = Riccati.dare(in A, in B, in Q, in R, ref S1);
                    var S2 = new floatMxN(2, 2, Allocator.Temp);
                    var i2 = Riccati.dare(in A, in B, in Q, in R, ref S2);

                    AssertEqInt(i1.iterations, i2.iterations);
                    for (int i = 0; i < 2; i++)
                        for (int j = 0; j < 2; j++)
                            AssertClose(S1[i, j], S2[i, j], (float)0);

                    A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); S1.Dispose(); S2.Dispose();
                    break;
                }

                case TestType.SmallCovarianceScale:
                {
                    // The DARE is homogeneous in (Q, R): scaling both by a scales S by exactly a.
                    // So the same instance solved large and solved small must agree after rescaling.
                    //
                    // This is what a convergence floor of 1 breaks. Below ||S|| = 1 the relative test
                    // silently becomes ABSOLUTE, the first doubling step already sits under it, and
                    // dare reports Converged on an S that is still essentially Q. Filter covariances
                    // live entirely in that regime, which is why Kalman.steadyStateGain rescales its
                    // inputs before calling here.
                    const double alpha = 1e-4;

                    var A = new floatMxN(2, 2, Allocator.Temp);
                    A[0, 0] = (float)1; A[0, 1] = (float)1; A[1, 0] = (float)0; A[1, 1] = (float)1;
                    var B = new floatMxN(2, 1, Allocator.Temp);
                    B[0, 0] = (float)0; B[1, 0] = (float)1;

                    var Q = new floatMxN(2, 2, Allocator.Temp);
                    Q[0, 0] = (float)1; Q[1, 1] = (float)1;
                    var R = new floatMxN(1, 1, Allocator.Temp);
                    R[0, 0] = (float)1;

                    var Sbig = new floatMxN(2, 2, Allocator.Temp);
                    AssertTrue(Riccati.dare(in A, in B, in Q, in R, ref Sbig).Solved);

                    var Qs = new floatMxN(2, 2, Allocator.Temp);
                    Qs[0, 0] = (float)alpha; Qs[1, 1] = (float)alpha;
                    var Rs = new floatMxN(1, 1, Allocator.Temp);
                    Rs[0, 0] = (float)alpha;

                    var Ssmall = new floatMxN(2, 2, Allocator.Temp);
                    AssertTrue(Riccati.dare(in A, in B, in Qs, in Rs, ref Ssmall).Solved);

                    for (int i = 0; i < 2; i++)
                        for (int j = 0; j < 2; j++)
                            AssertClose(Ssmall[i, j] / (float)alpha, Sbig[i, j],
                                        math.abs(Sbig[i, j]) * (float)0.01 + (float)0.01);

                    A.Dispose(); B.Dispose(); Q.Dispose(); R.Dispose(); Sbig.Dispose();
                    Qs.Dispose(); Rs.Dispose(); Ssmall.Dispose();
                    break;
                }
            }
        }

        static floatMxN One()
        {
            var M = new floatMxN(1, 1, Allocator.Temp);
            M[0, 0] = (float)1;
            return M;
        }

        void AssertTrue(bool cond)
        {
            if (!cond && Fail[0] == (float)0) { Fail[0] = (float)1; Fail[1] = (float)0; Fail[2] = (float)1; Fail[3] = (float)0; }
            Assert.IsTrue(cond);
        }

        void AssertEqInt(int got, int expected)
        {
            if (got != expected && Fail[0] == (float)0) { Fail[0] = (float)1; Fail[1] = (float)got; Fail[2] = (float)expected; Fail[3] = (float)(got - expected); }
            Assert.IsTrue(got == expected);
        }

        void AssertClose(float a, float b, float precision)
        {
            float diff = math.abs(a - b);
            if (!(diff <= precision) && Fail[0] == (float)0) { Fail[0] = (float)1; Fail[1] = a; Fail[2] = b; Fail[3] = diff; }
            Assert.IsTrue(diff <= precision);
        }
    }

